CREATE TABLE "StockWorkflow" ("id" TEXT PRIMARY KEY, "enabled" BOOLEAN NOT NULL DEFAULT false, "activeFrom" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "sourceSheet" TEXT NOT NULL);
CREATE TABLE "StockReservation" ("orderId" TEXT PRIMARY KEY, "messageKey" TEXT NOT NULL UNIQUE, "orderNumber" TEXT NOT NULL, "actor" TEXT NOT NULL, "items" JSONB NOT NULL, "status" TEXT NOT NULL DEFAULT 'QUEUED', "issues" JSONB NOT NULL DEFAULT '[]', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "StockSheetOperation" ("id" TEXT PRIMARY KEY, "kind" TEXT NOT NULL, "sourceSheet" TEXT NOT NULL, "snapshot" JSONB NOT NULL, "fingerprint" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'PREPARED', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "appliedAt" TIMESTAMP(3));
ALTER TABLE "StockDispatch" ADD COLUMN "historySnapshot" JSONB, ADD COLUMN "historySavedAt" TIMESTAMP(3);
